contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address caller) public payable {
        require(address(c).balance >= 0);
        address nonOwner = address(0x1234);
        // Ensure caller is not the owner by checking owner() and selecting a different address if needed
        if (caller == c.owner()) {
            nonOwner = address(0x5678);
        } else {
            nonOwner = caller;
        }
        // Precondition: ensure nonOwner is not the owner
        require(nonOwner != c.owner(), "caller must not be owner");
        bool reverted;
        // Attempt to call updateRoundImplementation as a non-owner
        c.updateRoundImplementation(payable(address(0x1111))); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        // Assert that the call reverted, because only owner can update
        assert(reverted == true);
    }
    receive() external payable {}
}

